/* Standalone SRAM survey for the BK7258, run straight off the reset vector.
 *
 * The header map says SRAM is six banks -- 0x28000000 and 0x28010000 at 64K,
 * then 0x28020000, 0x28040000, 0x28060000 and 0x28080000 at 128K -- but the
 * boot behaviour disagrees with it: a stack at 0x2803c800 works and one at
 * 0x28022464 does not, and both are supposedly bank SRAM2.  So rather than
 * trust the map, write and read back one word in each candidate region and
 * report what actually answers.
 *
 * Results come out on GPIO11 (UART0 TX -> CH340) as bursts of framing errors:
 * a long burst means the word survived the round trip, a short one means it
 * did not.  Candidates are reported in order with a fixed gap between them and
 * a longer gap between rounds, so the host decodes them by burst length.  An
 * address that faults instead of answering simply ends the round early, which
 * is itself the answer for that slot.
 *
 * Nothing here uses .data or .bss: the vector table and the candidate list are
 * const, everything else is a local.  The stack sits at the address the
 * factory firmware uses, which is the one address known to work.
 */

#include <stdint.h>

#define GPIO11        (*(volatile uint32_t *)0x4400042cul)
#define PAD_DRIVE_HI  2u          /* output value set, output-disable clear */
#define PAD_DRIVE_LO  0u

#define BURST_YES     200u        /* writable   -> long burst  */
#define BURST_NO      40u         /* unwritable -> short burst */
#define GAP_SLOT      450u        /* between candidates        */
#define GAP_ROUND     1600u       /* between rounds            */

static void spin(uint32_t n)
{
  volatile uint32_t i;

  for (i = 0; i < n; i++)
    {
    }
}

static void burst(uint32_t toggles, uint32_t gap)
{
  uint32_t i;

  for (i = 0; i < toggles; i++)
    {
      GPIO11 = (i & 1) ? PAD_DRIVE_HI : PAD_DRIVE_LO;
      spin(2000);
    }

  GPIO11 = PAD_DRIVE_HI;          /* UART idle is high: this reads as silence */

  for (i = 0; i < gap; i++)
    {
      spin(2000);
    }
}

static int survives(volatile uint32_t *p)
{
  uint32_t save = *p;

  *p = 0xa55a1234u;
  if (*p != 0xa55a1234u)
    {
      return 0;
    }

  *p = 0x5aa5edcbu;
  if (*p != 0x5aa5edcbu)
    {
      return 0;
    }

  *p = save;
  return 1;
}

void reset_main(void)
{
  static const uint32_t candidate[] =
    {
      0x28000000u, 0x28008000u,   /* SRAM0 low / high  */
      0x28010000u, 0x28018000u,   /* SRAM1 low / high  */
      0x28020000u, 0x28028000u,   /* SRAM2 first half  */
      0x28030000u, 0x28038000u,   /* SRAM2 second half */
      0x28040000u, 0x28060000u,   /* SRAM3, SRAM4      */
      0x28080000u,                /* SRAM5             */
    };

  for (; ; )
    {
      uint32_t i;

      for (i = 0; i < sizeof(candidate) / sizeof(candidate[0]); i++)
        {
          int ok = survives((volatile uint32_t *)candidate[i]);

          burst(ok ? BURST_YES : BURST_NO, GAP_SLOT);
        }

      burst(0, GAP_ROUND);
    }
}

__attribute__((section(".vectors"), used))
const uint32_t g_vectors[2] =
{
  0x2803c800u,                    /* Initial MSP: the factory firmware's */
  (uint32_t)reset_main            /* Reset, Thumb bit already set by GCC */
};

