/* Which addresses can actually hold the initial stack on this board?
 *
 * An earlier probe showed that every SRAM bank takes a word write and reads it
 * back, yet three of four measured stack addresses wedged the CPU before it
 * executed a single reportable instruction.  Holding a stack is evidently a
 * stronger requirement than storing a word, so test that requirement directly:
 * point MSP at each candidate, exercise it with a real call and a real push,
 * put MSP back, and move on.
 *
 * Reporting is announce-then-test: a burst on GPIO11 goes out BEFORE each
 * candidate is tried, so if a candidate wedges the CPU the stream simply stops
 * and the burst count names the one that did it.  Candidates that survive also
 * emit a second, shorter burst, so a clean run reads as pairs.
 *
 * The probe's own stack sits at 0x2803c800 -- the factory firmware's value, and
 * the only address so far confirmed to work.
 */

#include <stdint.h>

#define GPIO11        (*(volatile uint32_t *)0x4400042cul)
#define PAD_DRIVE_HI  2u
#define PAD_DRIVE_LO  0u

static void spin(uint32_t n)
{
  volatile uint32_t i;

  for (i = 0; i < n; i++)
    {
    }
}

static void burst(uint32_t toggles, uint32_t gap)
{
  uint32_t i;

  for (i = 0; i < toggles; i++)
    {
      GPIO11 = (i & 1) ? PAD_DRIVE_HI : PAD_DRIVE_LO;
      spin(1500);
    }

  GPIO11 = PAD_DRIVE_HI;

  for (i = 0; i < gap; i++)
    {
      spin(1500);
    }
}

/* Deliberately not inlined and deliberately stack-hungry: the point is to make
 * the candidate stack carry a call frame, a saved link register and a few
 * spilled locals, which is what the real startup path does to it.
 */

static __attribute__((noinline)) uint32_t stack_workout(uint32_t seed)
{
  volatile uint32_t scratch[8];
  uint32_t i;

  for (i = 0; i < 8; i++)
    {
      scratch[i] = seed + i;
    }

  for (i = 0; i < 8; i++)
    {
      seed ^= scratch[i];
    }

  return seed;
}

/* Run stack_workout() on a borrowed stack.  MSP is saved and restored around
 * the call, so a candidate that merely fails to store leaves the probe intact
 * and only a candidate that faults or hangs stops the stream.
 */

static __attribute__((noinline)) uint32_t try_stack(uint32_t sp)
{
  uint32_t old_sp;
  uint32_t result;

  __asm__ __volatile__
    (
      "mrs  %0, msp\n"
      "msr  msp, %2\n"
      "isb\n"
      "mov  r0, #1\n"
      "bl   stack_workout\n"
      "mov  %1, r0\n"
      "msr  msp, %0\n"
      "isb\n"
      : "=&r"(old_sp), "=&r"(result)
      : "r"(sp)
      : "r0", "r1", "r2", "r3", "r12", "lr", "cc", "memory"
    );

  return result;
}

void reset_main(void)
{
  static const uint32_t candidate[] =
    {
      0x28002468u,   /* SRAM0, aligned   -- measured as failing in situ */
      0x28012468u,   /* SRAM1, aligned                                  */
      0x28022468u,   /* SRAM2 low, aligned -- measured as failing       */
      0x28032468u,   /* SRAM2 high, aligned                             */
      0x2803c800u,   /* SRAM2 top, aligned -- the one known to work     */
      0x28042468u,   /* SRAM3                                           */
      0x28062468u,   /* SRAM4                                           */
      0x28082468u,   /* SRAM5                                           */
    };

  for (; ; )
    {
      uint32_t i;

      for (i = 0; i < sizeof(candidate) / sizeof(candidate[0]); i++)
        {
          burst(160, 400);                    /* announce candidate i     */
          (void)try_stack(candidate[i]);
          burst(50, 400);                     /* survived                 */
        }

      burst(0, 2000);                         /* end of round             */
    }
}

__attribute__((section(".vectors"), used))
const uint32_t g_vectors[2] =
{
  0x2803c800u,
  (uint32_t)reset_main
};

