127	/****************************************************************************
128	 * Name: bk7258_qspi_op
129	 *
130	 * Description:
131	 *   One indirect operation: first byte as the command, the rest through
132	 *   the FIFO as 1-wire data.  Returns when the engine reports done.
133	 *
134	 ****************************************************************************/
135	
136	static int bk7258_qspi_op(struct bk7258_qspi_dev_s *priv,
137	                          const uint8_t *buf, size_t nbytes)
138	{
139	  uint32_t word;
140	  uint32_t budget;
141	  size_t ndata = nbytes - 1;
142	  size_t i;
143	
144	  /* Scrub FIFO and stale status. */
145	
146	  qspi_putreg(priv, QSPI_RST_FIFO_OFFSET, QSPI_RST_SW_FIFO);
147	  qspi_putreg(priv, QSPI_RST_FIFO_OFFSET, 0);
148	  qspi_putreg(priv, QSPI_STATUS_CLR_OFFSET, 0xff);
149	  qspi_putreg(priv, QSPI_STATUS_CLR_OFFSET, 0);
150	
151	  /* Data first: the FIFO must hold everything before the engine starts. */
152	
153	  for (i = 0; i < ndata; i += 4)
154	    {
155	      word = buf[1 + i];
156	
157	      if (i + 1 < ndata)
158	        {
159	          word |= (uint32_t)buf[2 + i] << 8;
160	        }
161	
162	      if (i + 2 < ndata)
163	        {
164	          word |= (uint32_t)buf[3 + i] << 16;
165	        }
166	
167	      if (i + 3 < ndata)
168	        {
169	          word |= (uint32_t)buf[4 + i] << 24;
170	        }
171	
172	      qspi_putreg(priv, QSPI_FIFO_OFFSET, word);
173	    }
174	
175	  /* Command block: one 1-wire command byte, then the data phase. */
176	
177	  qspi_putreg(priv, QSPI_CMD_C_L_OFFSET, 0);
178	  qspi_putreg(priv, QSPI_CMD_C_H_OFFSET, buf[0]);
179	  qspi_putreg(priv, QSPI_CMD_C_CFG1_OFFSET, QSPI_CFG1_ONE_CMD_BYTE);
180	  qspi_putreg(priv, QSPI_CMD_C_CFG2_OFFSET,
181	              QSPI_CFG2_DATA_LEN(ndata) |
182	              (ndata > 0 ? QSPI_CFG2_DUMMY_MODE_WR : 0) |
183	              QSPI_CFG2_START);
184	
185	  budget = 200000;
186	
187	  while ((qspi_getreg(priv, QSPI_STATUS_OFFSET) & QSPI_STATUS_CMD_DONE) == 0)
188	    {
189	      if (--budget == 0)
190	        {
191	          return -ETIMEDOUT;
192	        }
193	    }
194	
195	  qspi_putreg(priv, QSPI_STATUS_CLR_OFFSET, QSPI_STATUS_CMD_DONE);
196	  qspi_putreg(priv, QSPI_STATUS_CLR_OFFSET, 0);
197	
198	  return OK;
199	}
