            (3u << 15) | (0x1fu << 17),
            (3u << 15) | (19u << 17));

/* Liveness check: with the input path left on, a running MCLK
 * shows both levels under CPU sampling; a dead pad never moves.
 */

  {
    extern bool bk7258_gpio_read(int pin);
    int transitions = 0;
    bool last = bk7258_gpio_read(27);
    int n;

    for (n = 0; n < 20000; n++)
      {
        bool cur = bk7258_gpio_read(27);
        if (cur != last)
