/****************************************************************************
 * apps/face/face_main.c
 *
 * The complete robot face: procedural eyes idle on both panels (gaze
 * wander + blinks, same engine as the eyes app), and the vendor's own
 * MJPEG expression clips play on demand -- 320x160 AVI frames from the
 * SD card, software-decoded (TJpgDec) and split down the middle onto
 * the two 160x160 panels.
 *
 * Buttons: S2 plays the next expression, S3 exits (S1 shares its GPIO
 * with the SD-card LDO and is left alone).
 *
 * Usage: face [expression-name]   e.g. "face HAPPY" plays one clip;
 *        plain "face" runs the interactive demo.
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/video/fb.h>
#include <nuttx/input/buttons.h>

#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/mount.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "tjpgd.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define EYE_XRES   160
#define EYE_YRES   160
#define EYE_CX     80
#define EYE_CY     80

#define R_RING     34
#define R_IRIS     29
#define R_PUP      13
#define R_HIL      4
#define G_MAX      18

#define C_BG       0x0000
#define C_RING     0x07ff
#define C_IRIS     0x0350
#define C_PUP      0x0841
#define C_HIL      0xffff

#define FRAME_US   33000

#define AVI_W      320
#define CHUNK_MAX  (64 * 1024)
#define TJPGD_POOL 8192

#define BTN_S2     (1u << 1)
#define BTN_S3     (1u << 2)

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct eye_fb_s
{
  int fd;
  uint16_t *mem;
  size_t len;
  int stride_px;
};

struct jpeg_src_s
{
  const uint8_t *data;
  size_t size;
  size_t pos;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const uint8_t g_lidfrac[] =
{
  35, 75, 100, 100, 80, 55, 30, 10, 0
};

static const char *g_exprs[] =
{
  "HAPPY", "CURIOUS", "LOVE", "SURPRISE", "THINKING",
  "SAD", "SLEEPY", "ANGRY", "NEUTRAL"
};

#define NEXPRS (sizeof(g_exprs) / sizeof(g_exprs[0]))

static struct eye_fb_s g_eye[2];

/****************************************************************************
 * Private Functions: shared plumbing
 ****************************************************************************/

static uint32_t now_ms(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint32_t)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
}

static int eye_open(struct eye_fb_s *e, const char *path)
{
  struct fb_planeinfo_s pinfo;

  e->fd = open(path, O_RDWR);
  if (e->fd < 0)
    {
      printf("face: cannot open %s\n", path);
      return -1;
    }

  if (ioctl(e->fd, FBIOGET_PLANEINFO, (unsigned long)(uintptr_t)&pinfo) < 0)
    {
      close(e->fd);
      return -1;
    }

  e->len = pinfo.fblen;
  e->stride_px = pinfo.stride / 2;
  e->mem = mmap(NULL, pinfo.fblen, PROT_READ | PROT_WRITE,
                MAP_SHARED | MAP_FILE, e->fd, 0);
  return (e->mem == MAP_FAILED) ? -1 : 0;
}

static void eye_flush(struct eye_fb_s *e, int x0, int y0, int x1, int y1)
{
  struct fb_area_s area;

  area.x = x0;
  area.y = y0;
  area.w = x1 - x0 + 1;
  area.h = y1 - y0 + 1;
  ioctl(e->fd, FBIO_UPDATE, (unsigned long)(uintptr_t)&area);
}

/****************************************************************************
 * Private Functions: procedural eyes (idle mode)
 ****************************************************************************/

static void eye_render(struct eye_fb_s *e, int cx, int cy, int lid,
                       int x0, int y0, int x1, int y1)
{
  int px = cx + ((cx - EYE_CX) >> 3);
  int py = cy + ((cy - EYE_CY) >> 3);
  int hx = cx - 11;
  int hy = cy - 11;
  int x;
  int y;

  for (y = y0; y <= y1; y++)
    {
      uint16_t *row = e->mem + y * e->stride_px;

      for (x = x0; x <= x1; x++)
        {
          uint16_t c = C_BG;

          if (y >= lid)
            {
              int dx = x - cx;
              int dy = y - cy;
              int d2 = dx * dx + dy * dy;

              if (d2 <= R_RING * R_RING)
                {
                  int ex = x - hx;
                  int ey = y - hy;
                  int qx = x - px;
                  int qy = y - py;

                  if (ex * ex + ey * ey <= R_HIL * R_HIL)
                    {
                      c = C_HIL;
                    }
                  else if (qx * qx + qy * qy <= R_PUP * R_PUP)
                    {
                      c = C_PUP;
                    }
                  else if (d2 <= R_IRIS * R_IRIS)
                    {
                      c = C_IRIS;
                    }
                  else
                    {
                      c = C_RING;
                    }
                }
            }

          row[x] = c;
        }
    }
}

/****************************************************************************
 * Private Functions: MJPEG expression playback
 ****************************************************************************/

static size_t jpeg_in(JDEC *jd, uint8_t *buf, size_t len)
{
  struct jpeg_src_s *src = (struct jpeg_src_s *)jd->device;

  if (src->pos + len > src->size)
    {
      len = src->size - src->pos;
    }

  if (buf != NULL)
    {
      memcpy(buf, src->data + src->pos, len);
    }

  src->pos += len;
  return len;
}

/* Frame columns 0-159 land on the viewer-left panel (fb1), 160-319 on
 * the viewer-right one (fb0).
 */

static int jpeg_out(JDEC *jd, void *bitmap, JRECT *rect)
{
  const uint16_t *src = (const uint16_t *)bitmap;
  int w = rect->right - rect->left + 1;
  int y;
  int x;

  for (y = rect->top; y <= rect->bottom && y < EYE_YRES; y++)
    {
      for (x = rect->left; x <= rect->right && x < AVI_W; x++)
        {
          uint16_t px = src[(y - rect->top) * w + (x - rect->left)];

          if (x < EYE_XRES)
            {
              g_eye[1].mem[y * g_eye[1].stride_px + x] = px;
            }
          else
            {
              g_eye[0].mem[y * g_eye[0].stride_px + (x - EYE_XRES)] = px;
            }
        }
    }

  return 1;
}

/****************************************************************************
 * Name: play_avi
 *
 * Description:
 *   Stream one MJPEG AVI from the SD card onto both panels.  Returns 0
 *   at end of clip, 1 if the user pressed S3 to abort, negative errno
 *   on real trouble.
 *
 ****************************************************************************/

static int play_avi(const char *name, int btnfd)
{
  char path[48];
  uint8_t *chunk = NULL;
  uint8_t *pool = NULL;
  int fd;
  int ret = 0;
  uint32_t hdr[3];

  snprintf(path, sizeof(path), "/mnt/%s.AVI", name);
  fd = open(path, O_RDONLY);
  if (fd < 0)
    {
      printf("face: no %s\n", path);
      return -1;
    }

  chunk = malloc(CHUNK_MAX);
  pool  = malloc(TJPGD_POOL);
  if (chunk == NULL || pool == NULL)
    {
      ret = -1;
      goto out;
    }

  /* Walk top-level RIFF chunks until the movi LIST, then play every
   * 00dc entry inside it.
   */

  if (read(fd, hdr, 12) != 12)
    {
      ret = -1;
      goto out;
    }

  for (; ; )
    {
      uint32_t fcc;
      uint32_t size;

      if (read(fd, hdr, 8) != 8)
        {
          goto out;                    /* clean end of file */
        }

      fcc  = hdr[0];
      size = hdr[1];

      if (fcc == 0x5453494c)           /* "LIST" */
        {
          uint32_t ltype;

          if (read(fd, &ltype, 4) != 4)
            {
              goto out;
            }

          if (ltype == 0x69766f6d)     /* "movi": descend, do not skip */
            {
              continue;
            }

          lseek(fd, size - 4 + (size & 1), SEEK_CUR);
        }
      else if (fcc == 0x63643030)      /* "00dc": one MJPEG frame */
        {
          uint32_t t0 = now_ms();
          btn_buttonset_t btn = 0;

          if (size > CHUNK_MAX)
            {
              lseek(fd, size + (size & 1), SEEK_CUR);
              continue;
            }

          if (read(fd, chunk, size) != (ssize_t)size)
            {
              goto out;
            }

          if ((size & 1) != 0)
            {
              lseek(fd, 1, SEEK_CUR);
            }

            {
              struct jpeg_src_s src =
              {
                .data = chunk, .size = size, .pos = 0
              };

              JDEC jd;

              if (jd_prepare(&jd, jpeg_in, pool, TJPGD_POOL, &src) == JDR_OK)
                {
                  jd_decomp(&jd, jpeg_out, 0);
                }
            }

          eye_flush(&g_eye[0], 0, 0, EYE_XRES - 1, EYE_YRES - 1);
          eye_flush(&g_eye[1], 0, 0, EYE_XRES - 1, EYE_YRES - 1);

          /* Abort key, then pace toward the clip's 20 fps. */

          if (btnfd >= 0 &&
              read(btnfd, &btn, sizeof(btn)) == sizeof(btn) &&
              (btn & BTN_S3) != 0)
            {
              ret = 1;
              goto out;
            }

            {
              uint32_t spent = now_ms() - t0;

              if (spent < 50)
                {
                  usleep((50 - spent) * 1000);
                }
            }
        }
      else
        {
          lseek(fd, size + (size & 1), SEEK_CUR);
        }
    }

out:
  free(chunk);
  free(pool);
  close(fd);
  return ret;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
  int btnfd;
  unsigned int expr = 0;
  btn_buttonset_t last = 0;
  int gx = 0;
  int gy = 0;
  int tx = 0;
  int ty = 0;
  int blink = -1;
  int px0 = 0;
  int py0 = 0;
  int px1 = EYE_XRES - 1;
  int py1 = EYE_YRES - 1;
  uint32_t next_gaze;
  uint32_t next_blink;
  int i;

  if (eye_open(&g_eye[0], "/dev/fb0") < 0 ||
      eye_open(&g_eye[1], "/dev/fb1") < 0)
    {
      return 1;
    }

  mount("/dev/mmcsd0", "/mnt", "vfat", 0, NULL);  /* idempotent-ish */

  btnfd = open("/dev/buttons", O_RDONLY | O_NONBLOCK);

  /* One-shot mode: play the named clip and exit. */

  if (argc > 1)
    {
      play_avi(argv[1], btnfd);
      return 0;
    }

  printf("face: S2 = next expression, S3 = quit\n");
  srand(now_ms());
  next_gaze  = now_ms() + 1500;
  next_blink = now_ms() + 2200;

  for (; ; )
    {
      uint32_t t0 = now_ms();
      btn_buttonset_t btn = 0;
      int cx;
      int cy;
      int lid;
      int x0;
      int y0;
      int x1;
      int y1;

      /* Buttons: S2 rising edge plays a clip, S3 quits. */

      if (btnfd >= 0 &&
          read(btnfd, &btn, sizeof(btn)) == sizeof(btn))
        {
          if ((btn & BTN_S3) != 0)
            {
              break;
            }

          if ((btn & BTN_S2) != 0 && (last & BTN_S2) == 0)
            {
              printf("face: %s\n", g_exprs[expr]);
              if (play_avi(g_exprs[expr], btnfd) < 0)
                {
                  printf("face: (clip missing, skipping)\n");
                }

              expr = (expr + 1) % NEXPRS;

              /* Force a full idle repaint after the clip. */

              px0 = 0;
              py0 = 0;
              px1 = EYE_XRES - 1;
              py1 = EYE_YRES - 1;
            }

          last = btn;
        }

      /* Idle eyes: identical behavior to the eyes app. */

      if (blink < 0 && t0 >= next_gaze)
        {
          do
            {
              tx = rand() % (2 * G_MAX + 1) - G_MAX;
              ty = rand() % (2 * G_MAX + 1) - G_MAX;
            }
          while (tx * tx + ty * ty > G_MAX * G_MAX);

          next_gaze = t0 + 1200 + rand() % 1800;
        }

      if (gx != tx)
        {
          int step = (tx - gx) / 4;
          gx += (step != 0) ? step : ((tx > gx) ? 1 : -1);
        }

      if (gy != ty)
        {
          int step = (ty - gy) / 4;
          gy += (step != 0) ? step : ((ty > gy) ? 1 : -1);
        }

      if (blink < 0 && t0 >= next_blink)
        {
          blink = 0;
        }

      if (blink >= 0)
        {
          lid = (EYE_CY - R_RING) +
                (2 * R_RING * g_lidfrac[blink]) / 100;
          blink++;
          if (blink >= (int)sizeof(g_lidfrac))
            {
              blink = -1;
              next_blink = t0 + 2000 + rand() % 2500;
            }
        }
      else
        {
          lid = 0;
        }

      cx = EYE_CX + gx;
      cy = EYE_CY + gy;

      x0 = cx - R_RING - 1;
      y0 = cy - R_RING - 1;
      x1 = cx + R_RING + 1;
      y1 = cy + R_RING + 1;

      if (px0 < x0) x0 = px0;
      if (py0 < y0) y0 = py0;
      if (px1 > x1) x1 = px1;
      if (py1 > y1) y1 = py1;

      if (x0 < 0) x0 = 0;
      if (y0 < 0) y0 = 0;
      if (x1 > EYE_XRES - 1) x1 = EYE_XRES - 1;
      if (y1 > EYE_YRES - 1) y1 = EYE_YRES - 1;

      for (i = 0; i < 2; i++)
        {
          eye_render(&g_eye[i], cx, cy, lid, x0, y0, x1, y1);
          eye_flush(&g_eye[i], x0, y0, x1, y1);
        }

      px0 = cx - R_RING - 1;
      py0 = cy - R_RING - 1;
      px1 = cx + R_RING + 1;
      py1 = cy + R_RING + 1;

        {
          uint32_t spent = now_ms() - t0;

          if (spent * 1000 < FRAME_US)
            {
              usleep(FRAME_US - spent * 1000);
            }
        }
    }

  for (i = 0; i < 2; i++)
    {
      munmap(g_eye[i].mem, g_eye[i].len);
      close(g_eye[i].fd);
    }

  if (btnfd >= 0)
    {
      close(btnfd);
    }

  return 0;
}

/****************************************************************************
 * apps/face/face_main.c
 *
 * The robot face, all vendor art: NEUTRAL.AVI loops as the idle state
 * and S2 cuts straight to the next expression clip -- pressed at any
 * moment, including mid-clip.  Every frame is a 320x160 MJPEG from the
 * SD card, software-decoded (TJpgDec) and split down the middle onto
 * the two 160x160 panels.  S3 quits.
 *
 * Usage: face [expression-name]   e.g. "face HAPPY" plays one clip;
 *        plain "face" runs the interactive demo.
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/video/fb.h>
#include <nuttx/input/buttons.h>

#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/mount.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "tjpgd.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define EYE_XRES   160
#define EYE_YRES   160
#define AVI_W      320

#define CHUNK_MAX  (64 * 1024)
#define TJPGD_POOL 8192

#define BTN_S2     (1u << 1)
#define BTN_S3     (1u << 2)

/* play_avi() outcomes */

#define PLAY_END   0                   /* clip finished naturally */
#define PLAY_QUIT  1                   /* S3: leave the program */
#define PLAY_NEXT  2                   /* S2: cut to the next clip */

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct eye_fb_s
{
  int fd;
  uint16_t *mem;
  size_t len;
  int stride_px;
};

struct jpeg_src_s
{
  const uint8_t *data;
  size_t size;
  size_t pos;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const char *g_exprs[] =
{
  "HAPPY", "CURIOUS", "LOVE", "SURPRISE", "THINKING",
  "SAD", "SLEEPY", "ANGRY"
};

#define NEXPRS (sizeof(g_exprs) / sizeof(g_exprs[0]))

static struct eye_fb_s g_eye[2];
static btn_buttonset_t g_btn_last;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static uint32_t now_ms(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint32_t)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
}

static int eye_open(struct eye_fb_s *e, const char *path)
{
  struct fb_planeinfo_s pinfo;

  e->fd = open(path, O_RDWR);
  if (e->fd < 0)
    {
      printf("face: cannot open %s\n", path);
      return -1;
    }

  if (ioctl(e->fd, FBIOGET_PLANEINFO, (unsigned long)(uintptr_t)&pinfo) < 0)
    {
      close(e->fd);
      return -1;
    }

  e->len = pinfo.fblen;
  e->stride_px = pinfo.stride / 2;
  e->mem = mmap(NULL, pinfo.fblen, PROT_READ | PROT_WRITE,
                MAP_SHARED | MAP_FILE, e->fd, 0);
  return (e->mem == MAP_FAILED) ? -1 : 0;
}

static void eye_flush_full(struct eye_fb_s *e)
{
  struct fb_area_s area;

  area.x = 0;
  area.y = 0;
  area.w = EYE_XRES;
  area.h = EYE_YRES;
  ioctl(e->fd, FBIO_UPDATE, (unsigned long)(uintptr_t)&area);
}

/****************************************************************************
 * Name: btn_event
 *
 * Description:
 *   Poll the buttons and report rising edges: PLAY_QUIT for S3,
 *   PLAY_NEXT for S2, 0 for nothing new.  Kept as the single reader of
 *   button state so no press is ever swallowed between modes.
 *
 ****************************************************************************/

static int btn_event(int btnfd)
{
  btn_buttonset_t btn = 0;
  int ev = 0;

  if (btnfd < 0 ||
      read(btnfd, &btn, sizeof(btn)) != sizeof(btn))
    {
      return 0;
    }

  if ((btn & BTN_S3) != 0 && (g_btn_last & BTN_S3) == 0)
    {
      ev = PLAY_QUIT;
    }
  else if ((btn & BTN_S2) != 0 && (g_btn_last & BTN_S2) == 0)
    {
      ev = PLAY_NEXT;
    }

  g_btn_last = btn;
  return ev;
}

/****************************************************************************
 * MJPEG decode plumbing
 ****************************************************************************/

static size_t jpeg_in(JDEC *jd, uint8_t *buf, size_t len)
{
  struct jpeg_src_s *src = (struct jpeg_src_s *)jd->device;

  if (src->pos + len > src->size)
    {
      len = src->size - src->pos;
    }

  if (buf != NULL)
    {
      memcpy(buf, src->data + src->pos, len);
    }

  src->pos += len;
  return len;
}

/* Frame columns 0-159 land on the viewer-left panel (fb1), 160-319 on
 * the viewer-right one (fb0).
 */

static int jpeg_out(JDEC *jd, void *bitmap, JRECT *rect)
{
  const uint16_t *src = (const uint16_t *)bitmap;
  int w = rect->right - rect->left + 1;
  int y;
  int x;

  for (y = rect->top; y <= rect->bottom && y < EYE_YRES; y++)
    {
      for (x = rect->left; x <= rect->right && x < AVI_W; x++)
        {
          uint16_t px = src[(y - rect->top) * w + (x - rect->left)];

          if (x < EYE_XRES)
            {
              g_eye[1].mem[y * g_eye[1].stride_px + x] = px;
            }
          else
            {
              g_eye[0].mem[y * g_eye[0].stride_px + (x - EYE_XRES)] = px;
            }
        }
    }

  return 1;
}

/****************************************************************************
 * Name: play_avi
 *
 * Description:
 *   Stream one MJPEG AVI onto both panels, checking the buttons after
 *   every frame.  Returns PLAY_END / PLAY_QUIT / PLAY_NEXT, or a
 *   negative value when the file cannot be played at all.
 *
 ****************************************************************************/

static int play_avi(const char *name, int btnfd)
{
  char path[48];
  uint8_t *chunk = NULL;
  uint8_t *pool = NULL;
  int fd;
  int ret = PLAY_END;
  uint32_t hdr[3];

  snprintf(path, sizeof(path), "/mnt/%s.AVI", name);
  fd = open(path, O_RDONLY);
  if (fd < 0)
    {
      return -1;
    }

  chunk = malloc(CHUNK_MAX);
  pool  = malloc(TJPGD_POOL);
  if (chunk == NULL || pool == NULL)
    {
      ret = -1;
      goto out;
    }

  if (read(fd, hdr, 12) != 12)
    {
      ret = -1;
      goto out;
    }

  for (; ; )
    {
      uint32_t fcc;
      uint32_t size;

      if (read(fd, hdr, 8) != 8)
        {
          goto out;                    /* natural end of clip */
        }

      fcc  = hdr[0];
      size = hdr[1];

      if (fcc == 0x5453494c)           /* "LIST" */
        {
          uint32_t ltype;

          if (read(fd, &ltype, 4) != 4)
            {
              goto out;
            }

          if (ltype == 0x69766f6d)     /* "movi": descend, do not skip */
            {
              continue;
            }

          lseek(fd, size - 4 + (size & 1), SEEK_CUR);
        }
      else if (fcc == 0x63643030)      /* "00dc": one MJPEG frame */
        {
          uint32_t t0 = now_ms();
          int ev;

          if (size > CHUNK_MAX)
            {
              lseek(fd, size + (size & 1), SEEK_CUR);
              continue;
            }

          if (read(fd, chunk, size) != (ssize_t)size)
            {
              goto out;
            }

          if ((size & 1) != 0)
            {
              lseek(fd, 1, SEEK_CUR);
            }

            {
              struct jpeg_src_s src =
              {
                .data = chunk, .size = size, .pos = 0
              };

              JDEC jd;

              if (jd_prepare(&jd, jpeg_in, pool, TJPGD_POOL, &src) == JDR_OK)
                {
                  jd_decomp(&jd, jpeg_out, 0);
                }
            }

          eye_flush_full(&g_eye[0]);
          eye_flush_full(&g_eye[1]);

          ev = btn_event(btnfd);
          if (ev != 0)
            {
              ret = ev;
              goto out;
            }

            {
              uint32_t spent = now_ms() - t0;

              if (spent < 50)
                {
                  usleep((50 - spent) * 1000);
                }
            }
        }
      else
        {
          lseek(fd, size + (size & 1), SEEK_CUR);
        }
    }

out:
  free(chunk);
  free(pool);
  close(fd);
  return ret;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
  int btnfd;
  int cur = -1;                        /* -1 = NEUTRAL idle loop */
  int i;

  if (eye_open(&g_eye[0], "/dev/fb0") < 0 ||
      eye_open(&g_eye[1], "/dev/fb1") < 0)
    {
      return 1;
    }

  mount("/dev/mmcsd0", "/mnt", "vfat", 0, NULL);

  btnfd = open("/dev/buttons", O_RDONLY | O_NONBLOCK);
  g_btn_last = 0;

  if (argc > 1)
    {
      if (play_avi(argv[1], btnfd) < 0)
        {
          printf("face: cannot play %s\n", argv[1]);
        }

      return 0;
    }

  printf("face: NEUTRAL idle; S2 = next expression, S3 = quit\n");

  for (; ; )
    {
      const char *name = (cur < 0) ? "NEUTRAL" : g_exprs[cur];
      int r = play_avi(name, btnfd);

      if (r == PLAY_QUIT)
        {
          break;
        }
      else if (r == PLAY_NEXT)
        {
          cur = (cur < 0) ? 0 : (int)((cur + 1) % NEXPRS);
          printf("face: %s\n", g_exprs[cur]);
        }
      else if (r == PLAY_END)
        {
          if (cur >= 0)
            {
              cur = -1;                /* expression over: back to idle */
            }
        }
      else
        {
          printf("face: cannot play %s, quitting\n", name);
          break;
        }
    }

  for (i = 0; i < 2; i++)
    {
      munmap(g_eye[i].mem, g_eye[i].len);
      close(g_eye[i].fd);
    }

  if (btnfd >= 0)
    {
      close(btnfd);
    }

  return 0;
}

