289	/****************************************************************************
290	 * Name: gc9d01_putarea
291	 *
292	 * Description:
293	 *   Blast a whole rectangle in one panel transaction: window and RAMWR go
294	 *   out once, then nothing but pixel bytes.  The per-row path pays five
295	 *   small command transfers per line -- 160x per full screen -- which is
296	 *   what made the first bring-up visibly crawl.
297	 *
298	 ****************************************************************************/
299	
300	static int gc9d01_putarea(struct lcd_dev_s *dev, fb_coord_t row_start,
301	                          fb_coord_t row_end, fb_coord_t col_start,
302	                          fb_coord_t col_end, const uint8_t *buffer,
303	                          fb_coord_t stride)
304	{
305	  /* Rows are batched before hitting the bus: every SNDBLOCK is a full
306	   * indirect-engine round trip (fill, start, poll), so its fixed cost --
307	   * not the wire clock -- dominates small transfers.  Eight rows per
308	   * batch cuts the round trips 8x for the price of a 2.5 KB bounce.
309	   */
310	
311	  static uint8_t batchbuf[8 * GC9D01_XRES * 2];
312	
313	  struct gc9d01_dev_s *priv = (struct gc9d01_dev_s *)dev;
314	  fb_coord_t row = row_start;
315	  size_t width = col_end - col_start + 1;
316	  const uint16_t *src;
317	  uint8_t *dst;
318	  size_t i;
319	
320	  gc9d01_setwindow(priv, col_start, row_start, col_end, row_end);
321	  bk7258_gpio_write(priv->dc_pin, true);
322	
323	  while (row <= row_end)
324	    {
325	      size_t nrows = row_end - row + 1;
326	
327	      if (nrows > 8)
328	        {
329	          nrows = 8;
330	        }
331	
332	      dst = batchbuf;
333	
334	      for (i = 0; i < nrows; i++)
335	        {
336	          size_t x;
337	
338	          src = (const uint16_t *)(buffer + (row - row_start + i) * stride);
339	
340	          for (x = 0; x < width; x++)
341	            {
342	              *dst++ = src[x] >> 8;
343	              *dst++ = src[x] & 0xff;
344	            }
345	        }
346	
347	      SPI_SNDBLOCK(priv->spi, batchbuf, nrows * width * 2);
348	      row += nrows;
349	    }
350	
351	  return OK;
352	}
