  adv_data[2] = 0x01;                 /* flags AD: type */
  adv_data[3] = 0x06;                 /* general discoverable, LE only */
  adv_data[4] = (uint8_t)(nlen + 1);  /* name AD: length */
  adv_data[5] = 0x09;                 /* name AD: complete local name */
