                                    void (*cb)(int cmd, void *p));

/* Layout must match ble_adv_param_t in bk_ble_types.h field for field;
 * same compiler, so the padding agrees.
 */

struct ble_adv_param_s
{
  uint8_t  own_addr_type;
  uint8_t  adv_type;
  uint8_t  chnl_map;
  uint16_t adv_prop;
  uint32_t adv_intv_min;
  uint32_t adv_intv_max;
  uint8_t  prim_phy;
  uint8_t  second_phy;
  uint8_t  peer_addr_type;
  uint8_t  peer_addr[6];
};

static volatile int g_ble_cmd_seen;

static void ble_host_cmd_cb(int cmd, void *param)
{
  syslog(LOG_INFO, "ble: host cmd %d done\\n", cmd);
  g_ble_cmd_seen = 1;
}

static void ble_host_notice_cb(int notice, void *param)
{
  syslog(LOG_INFO, "ble: host notice %d\\n", notice);
}

static int host_wait(const char *what)
{
  int i;

  for (i = 0; i < 100 && g_ble_cmd_seen == 0; i++)
    {
      usleep(50 * 1000);
    }

  syslog(LOG_INFO, "ble: %s %s\\n", what,
         g_ble_cmd_seen ? "acknowledged" : "TIMED OUT");
  return g_ble_cmd_seen ? 0 : -1;
}

/****************************************************************************
 * Name: bk7258_ble_host_adv
 *
 * Description:
 *   Advertise through the closed host, following the vendor's own
 *   documented sequence and its parameter values.
 *
 ****************************************************************************/

int bk7258_ble_host_adv(const char *name)
{
  struct ble_adv_param_s p;
  uint8_t adv[31];
  size_t nlen = strlen(name);
  uint8_t idx;
  int ret;

  if (nlen > 24)
    {
      nlen = 24;
    }

  ret = bluetooth_host_init();
  syslog(LOG_INFO, "ble: host init -> %d\\n", ret);
  if (ret != 0)
    {
      return ret;
    }

  bk_ble_set_notice_cb(ble_host_notice_cb);
  sleep(1);

  idx = bk_ble_get_idle_actv_idx_handle();
  syslog(LOG_INFO, "ble: idle actv idx %u\\n", idx);
  if (idx == 0xff)
    {
      return -1;
    }

  memset(&p, 0, sizeof(p));
  p.own_addr_type = 0;
  p.adv_type      = 0;              /* legacy */
  p.chnl_map      = 7;
  p.adv_prop      = 3;              /* connectable + scannable */
  p.adv_intv_min  = 0x120;
  p.adv_intv_max  = 0x160;
  p.prim_phy      = 1;
  p.second_phy    = 1;

  g_ble_cmd_seen = 0;
  ret = bk_ble_create_advertising(idx, &p, ble_host_cmd_cb);
  syslog(LOG_INFO, "ble: create_adv -> %d\\n", ret);
  host_wait("create_adv");

  /* Raw AD structures; the host takes the length as an argument */

  adv[0] = 0x02;
  adv[1] = 0x01;
  adv[2] = 0x06;
  adv[3] = (uint8_t)(nlen + 1);
  adv[4] = 0x09;
  memcpy(adv + 5, name, nlen);

  g_ble_cmd_seen = 0;
  ret = bk_ble_set_adv_data(idx, adv, (uint8_t)(5 + nlen),
                            ble_host_cmd_cb);
  syslog(LOG_INFO, "ble: set_adv_data -> %d\\n", ret);
  host_wait("set_adv_data");

  g_ble_cmd_seen = 0;
  ret = bk_ble_start_advertising(idx, 0, ble_host_cmd_cb);
  syslog(LOG_INFO, "ble: start_adv -> %d\\n", ret);
  return host_wait("start_adv");
}

