static volatile int g_host_cmd;

static void host_cmd_cb(int cmd, void *param)
{
  syslog(LOG_INFO, "ble: host cmd %d done\\n", cmd);
  g_host_cmd = 1;
}

static void host_notice_cb(int notice, void *param)
{
  syslog(LOG_INFO, "ble: host notice %d\\n", notice);
}

static int host_wait(const char *what)
{
  int i;

  for (i = 0; i < 60 && g_host_cmd == 0; i++)
    {
      usleep(50 * 1000);
    }

  syslog(LOG_INFO, "ble: %s %s\\n", what, g_host_cmd ? "ack" : "TIMEOUT");
  return g_host_cmd ? 0 : -1;
}

int bk7258_ble_host_adv(const char *name)
{
  struct ble_adv_param_s p;
  uint8_t adv[31];
  size_t nlen = strlen(name);
  uint8_t idx;
  int ret;

  if (nlen > 24)
    {
      nlen = 24;
    }

  ret = bluetooth_host_init();
  syslog(LOG_INFO, "ble: host init -> %d\\n", ret);
  if (ret != 0)
    {
      return ret;
    }

  bk_ble_set_notice_cb(host_notice_cb);
  sleep(1);

  idx = bk_ble_get_idle_actv_idx_handle();
  syslog(LOG_INFO, "ble: idle actv idx %u\\n", idx);
  if (idx == 0xff)
    {
      return -1;
    }

  memset(&p, 0, sizeof(p));
  p.own_addr_type = 0;
  p.adv_type      = 0;
  p.chnl_map      = 7;
  p.adv_prop      = 3;
  p.adv_intv_min  = 0x120;
  p.adv_intv_max  = 0x160;
  p.prim_phy      = 1;
  p.second_phy    = 1;

  g_host_cmd = 0;
  syslog(LOG_INFO, "ble: create_adv -> %d\\n",
         bk_ble_create_advertising(idx, &p, host_cmd_cb));
  host_wait("create_adv");

  adv[0] = 0x02;
  adv[1] = 0x01;
  adv[2] = 0x06;
  adv[3] = (uint8_t)(nlen + 1);
  adv[4] = 0x09;
  memcpy(adv + 5, name, nlen);

  g_host_cmd = 0;
  syslog(LOG_INFO, "ble: set_adv_data -> %d\\n",
         bk_ble_set_adv_data(idx, adv, (uint8_t)(5 + nlen), host_cmd_cb));
  host_wait("set_adv_data");

  g_host_cmd = 0;
  syslog(LOG_INFO, "ble: start_adv -> %d\\n",
         bk_ble_start_advertising(idx, 0, host_cmd_cb));
  return host_wait("start_adv");
}

