      if (total > 0 && g_hci.txlen >= total)
        {
          ret = bk_ble_hci_raw_to_controller(g_hci.txfrm, g_hci.txlen);
          g_hci.txlen = 0;

          if (ret != 0)
            {
              nxmutex_unlock(&g_hci.lock);
              return -EIO;
            }
        }
    }

  nxmutex_unlock(&g_hci.lock);
  return (ssize_t)consumed;
}

