 * Name: hci_trace
 *
 * Description:
 *   Bounded record of the opening HCI dialogue.  A host bring-up is a
 *   fixed sequence of a few dozen frames, and when it stalls the only
 *   question worth answering is which command never came back; once
 *   scanning starts the same trace would be thousands of reports a
 *   minute, so it stops after HCI_TRACE_FRAMES.  Both directions share
 *   the budget deliberately: the interleaving is the evidence.
 *
 ****************************************************************************/

#define HCI_TRACE_FRAMES 64

static void hci_trace(char dir, FAR const uint8_t *buf, uint16_t len)
{
  if (g_hci.trace >= HCI_TRACE_FRAMES)
    {
      return;
    }

  g_hci.trace++;

  if (buf[0] == HCI_PKT_CMD && len >= 4)
    {
      syslog(LOG_INFO, "hci %c cmd %04x plen %u\n", dir,
             (unsigned)(buf[1] | (buf[2] << 8)), buf[3]);
    }
  else if (buf[0] == HCI_PKT_EVT && len >= 3)
    {
      syslog(LOG_INFO, "hci %c evt %02x len %u [%02x %02x %02x %02x]\n",
