/****************************************************************************
 * Name: hci_trace
 *
 * Description:
 *   Bounded record of the opening HCI dialogue, stored rather than
 *   printed.  A host bring-up is a fixed sequence of a few dozen frames,
 *   and when it stalls the only question worth answering is which
 *   command never came back.
 *
 *   Nothing here may block.  The receive side runs in the controller's
 *   own callback thread, and an earlier version that called syslog() from
 *   there moved the stall around between runs -- 115200 baud of console
 *   inside the controller's context is enough to lose the events the
 *   trace exists to observe.  So this records four fields and returns;
 *   bk7258_hci_trace_dump() prints them later from a shell task.
 *
 ****************************************************************************/

static void hci_trace(char dir, FAR const uint8_t *buf, uint16_t len)
{
  FAR struct hci_note_s *n;

  if (g_hci.trace >= HCI_TRACE_FRAMES)
    {
      return;
    }

  n = &g_hci.notes[g_hci.trace++];

  n->dir  = (uint8_t)dir;
  n->type = buf[0];
  n->len  = len;

  if (buf[0] == HCI_PKT_CMD && len >= 3)
    {
      n->code = (uint16_t)(buf[1] | (buf[2] << 8));
    }
  else if (buf[0] == HCI_PKT_EVT && len >= 2)
    {
      n->code = buf[1];
    }
  else
    {
      n->code = 0;
    }
}

/****************************************************************************
 * Name: bk7258_hci_trace_dump
 *
 * Description:
 *   Print what hci_trace() recorded.  Called from a shell task, where
 *   blocking on the console costs nothing.
 *
 ****************************************************************************/

void bk7258_hci_trace_dump(void)
{
  uint16_t i;

  syslog(LOG_INFO, "hci: ring %u used, %lu dropped, %u frames traced\n",
         hci_rx_used(), (unsigned long)g_hci.rxdrop, g_hci.trace);

  for (i = 0; i < g_hci.trace; i++)
    {
      FAR struct hci_note_s *n = &g_hci.notes[i];

      if (n->type == HCI_PKT_CMD)
        {
          syslog(LOG_INFO, "  %c cmd %04x len %u\n",
                 n->dir, n->code, n->len);
        }
      else if (n->type == HCI_PKT_EVT)
        {
          syslog(LOG_INFO, "  %c evt %02x len %u\n",
                 n->dir, n->code, n->len);
        }
      else
        {
          syslog(LOG_INFO, "  %c type %02x len %u\n",
                 n->dir, n->type, n->len);
        }
    }
}

