            "HCI_Reset",
            "LE_Read_Local_Features (after reset)"
          };

        int budget = (phase == 0) ? 6000 : 12000;
        int waited;
        int seen = 0;

        write(fd, phase == 1 ? rst : le, 4);
        printf("face: --- %s ---\n", what[phase]);

        for (waited = 0; waited < budget; waited += 50)
          {
            int n = read(fd, buf, sizeof(buf));
